-- enrich pdp like button click events with image search entrance and image_source
CREATE TEMPORARY VIEW dwd_image_search_click_selfjoin_${grass_region_without_quote} AS
SELECT
    pdp_like_button_click.user_id AS user_id
    ,pdp_like_button_click.platform AS platform
    ,COALESCE(pdp_like_button_click.md5, image_search_item_click.md5) AS md5
    ,pdp_like_button_click.feature_detail AS feature_detail
    ,pdp_like_button_click.page_type AS page_type
    ,pdp_like_button_click.page_section AS page_section
    ,pdp_like_button_click.target_type AS target_type
    ,COALESCE(pdp_like_button_click.search_mid, image_search_item_click.search_mid) AS search_mid
    ,COALESCE(pdp_like_button_click.search_entrance, image_search_item_click.search_entrance) AS search_entrance
    ,pdp_like_button_click.liked AS liked
    ,pdp_like_button_click.is_back AS is_back
    ,pdp_like_button_click.place_order_gmv AS place_order_gmv
    ,pdp_like_button_click.place_order_gmv_local AS place_order_gmv_local
    ,pdp_like_button_click.location AS location
    ,COALESCE(pdp_like_button_click.item_similarity, image_search_item_click.item_similarity)  AS item_similarity
    ,COALESCE(pdp_like_button_click.image_source, image_search_item_click.image_source)  AS image_source
    ,pdp_like_button_click.is_ads AS is_ads
    ,pdp_like_button_click.camera_page_version AS camera_page_version
    ,pdp_like_button_click.pre_source_page_type AS pre_source_page_type
    ,pdp_like_button_click.pre_source_target_type AS pre_source_target_type
    ,pdp_like_button_click.pre_source_event_id AS pre_source_event_id
    ,pdp_like_button_click.event_id AS event_id
    ,pdp_like_button_click.local_hour AS local_hour
    ,pdp_like_button_click.local_date AS local_date
    ,pdp_like_button_click.regional_date AS regional_date
    ,pdp_like_button_click.regional_hour AS regional_hour
    ,pdp_like_button_click.operation AS operation
    ,pdp_like_button_click.operation_cnt AS operation_cnt
    ,pdp_like_button_click.grass_region AS grass_region 
FROM
    dwd_image_search_${grass_region_without_quote} AS pdp_like_button_click
LEFT JOIN
    dwd_image_search_${grass_region_without_quote} AS image_search_item_click
ON
    pdp_like_button_click.pre_source_page_type = 'image_search'
    AND pdp_like_button_click.pre_source_target_type = 'item'
    AND pdp_like_button_click.page_type = 'product'
    AND pdp_like_button_click.target_type = 'like_button'
    AND image_search_item_click.page_type = 'image_search'
    AND image_search_item_click.target_type = 'item'
    AND pdp_like_button_click.pre_source_event_id = image_search_item_click.event_id
    AND pdp_like_button_click.operation = 'click'
    AND image_search_item_click.operation = 'click';

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_image_search_aggregated_${grass_region_without_quote} AS
SELECT
    user_id,
    platform,
    md5,
    feature_detail,
    page_type,
    page_section,
    target_type,
    CASE
        WHEN 
            page_type IN ('search', 'home', 'mall', 'pre_search', 'find_similar_products', 'shop_category_landing')
            AND target_type IN ('image_search_button', 'try_image_search_button')
            AND operation IN ('impression', 'click')
        THEN
            CASE
                WHEN page_type = 'home' THEN 'Home'
                WHEN page_type = 'pre_search' THEN 'PRESEARCH'
                WHEN page_type = 'search' THEN 'SEARCH_RESULT'
                WHEN page_type = 'find_similar_products' THEN 'find_similar'
                WHEN page_type = 'mall' THEN 'MALL'
            END
        ELSE search_entrance
    END AS search_entrance,
    image_source,
    liked,
    sum(
        CASE WHEN operation = 'impression' THEN operation_cnt ELSE 0 END
    ) AS imp_cnt,
    sum(
        CASE WHEN operation = 'click' THEN operation_cnt ELSE 0 END
    ) AS click_cnt,
    sum(
        CASE WHEN operation = 'ppv' AND is_back = false THEN operation_cnt ELSE 0 END
    ) AS ppv_cnt,
    sum(
        CASE WHEN operation = 'view' AND is_back = false THEN operation_cnt ELSE 0 END
    ) AS view_cnt,
    sum(
        CASE WHEN operation = 'cart' THEN operation_cnt ELSE 0 END
    ) AS cart_cnt,
    sum(
        CASE WHEN operation = 'order' THEN operation_cnt ELSE 0 END
    ) AS order_cnt,
    sum(
        CASE WHEN operation = 'order' THEN place_order_gmv ELSE 0 END
    ) AS gmv,
    sum(
        CASE WHEN operation = 'order' THEN place_order_gmv_local ELSE 0 END
    ) AS gmv_local,
    sum(
        if(
            page_type = 'image_search'
            AND target_type = 'item'
            AND operation = 'click',
            location,
            0
        )
    ) AS click_location_sum,
    sum(
        if(
            page_type = 'image_search'
            AND target_type = 'item'
            AND operation = 'cart',
            location,
            0
        )
    ) AS cart_location_sum,
    sum(
        if(
            page_type = 'image_search'
            AND target_type = 'item'
            AND operation = 'impression'
            AND location = 0,
            item_similarity,
            0
        )
    ) top1_similarity_sum,
    sum(
        if(
            page_type = 'image_search'
            AND target_type = 'item'
            AND operation = 'impression'
            AND location = 0,
            1,
            0
        )
    ) top1_item_imp_cnt,
    coalesce(is_ads,false)  as is_ads,
    camera_page_version,
    local_hour,
    regional_date,
    regional_hour,
    operation
FROM
    dwd_image_search_click_selfjoin_${grass_region_without_quote}
WHERE 
    grass_region IN (${grass_region})
    AND local_date = ${local_date}
    AND local_hour IN (${local_hour})
    AND operation IN (${operation})
GROUP BY
    user_id,
    platform,
    md5,
    feature_detail,
    page_type,
    page_section,
    target_type,
    search_entrance,
    image_source,
    liked,
    is_ads,
    camera_page_version,
    local_hour,
    regional_date,
    regional_hour,
    operation;

